@staticmethod
def _validate_acceptance_checks(
    checks_raw: Any,
    final_patch: str,
) -> tuple[list[dict[str, str]], list[str]]:
    """Prüft PASS-Belege deterministisch gegen den tatsächlich aktuellen Diff."""
    validated: list[dict[str, str]] = []
    problems: list[str] = []

    if not isinstance(checks_raw, list) or not checks_raw:
        return [], ["Acceptance-PASS enthält keine strukturierten Anforderungsbelege."]

    seen_requirements: set[str] = set()
    for index, item in enumerate(checks_raw, 1):
        if not isinstance(item, dict):
            problems.append(f"Check {index} ist kein strukturiertes Objekt.")
            continue

        requirement = str(item.get("requirement", "")).strip()
        path = str(item.get("path", "")).strip()
        evidence = str(item.get("evidence", "")).strip()
        reason = str(item.get("reason", "")).strip()

        if not requirement or not path or not evidence or not reason:
            problems.append(
                f"Check {index} benötigt requirement, path, evidence und reason."
            )
            continue
        if len(evidence) < 4:
            problems.append(f"Check {index} enthält einen zu kurzen Beleg.")
            continue

        requirement_key = " ".join(requirement.lower().split())
        if requirement_key in seen_requirements:
            problems.append(f"Check {index} wiederholt dieselbe Anforderung ohne zusätzlichen Nachweis.")
            continue
        seen_requirements.add(requirement_key)

        if path not in final_patch:
            problems.append(
                f"{path}: behaupteter Acceptance-Pfad kommt im finalen Diff nicht vor "
                f"(Anforderung: {shorten(redact(requirement), 180)})."
            )
            continue
        if evidence not in final_patch:
            problems.append(
                f"{path}: behaupteter Acceptance-Beleg ist im finalen Diff nicht vorhanden "
                f"(Anforderung: {shorten(redact(requirement), 180)}; "
                f"Beleg: {shorten(redact(evidence), 180)})."
            )
            continue

        validated.append({
            "requirement": shorten(redact(requirement), 500),
            "path": shorten(redact(path), 300),
            "evidence": shorten(redact(evidence), 700),
            "reason": shorten(redact(reason), 700),
        })

    return validated, problems

def _run_acceptance_review(self, coder_review: str, first_review: dict[str, Any]) -> dict[str, Any]:
    """Zweite frische Prüfung mit deterministisch validierten PASS-Belegen."""
    if self.reviewer_client is None:
        return {"verdict": "PASS", "summary": "Zweite Akzeptanzprüfung deaktiviert.", "issues": [], "checks": []}

    full_patch = workspace_patch_text(self.state.workspace, sorted(self.state.files_changed))
    review_patch = full_patch
    if len(review_patch) > MAX_REVIEW_DIFF_CHARS:
        review_patch = truncate(review_patch, MAX_REVIEW_DIFF_CHARS)
    prompt = (
        "ORIGINALAUFTRAG:\n" + redact(self.state.task)
        + "\n\nGEÄNDERTE PFADE (Laufhistorie):\n" + "\n".join(sorted(self.state.files_changed))
        + "\n\nERFOLGREICHE/VERWENDETE PRÜFBEFEHLE:\n"
        + ("\n".join(redact(x) for x in self.state.test_commands) or "(keine)")
        + "\n\nCODER-SELBSTREVIEW:\n" + redact(coder_review)
        + "\n\nERSTER UNABHÄNGIGER REVIEW:\n" + redact(str(first_review.get("summary", "")))
        + "\n\nFINALER DIFF:\n" + redact(review_patch)
    )
    messages = [
        {"role": "system", "content": ACCEPTANCE_REVIEW_SYSTEM_PROMPT},
        {"role": "user", "content": prompt},
    ]
    parsed = self._review_json_call(
        messages,
        ACCEPTANCE_REVIEW_MAX_OUTPUT_TOKENS,
        stage="acceptance_review",
    )
    verdict = str(parsed.get("verdict", "")).strip().upper()
    issues_raw = parsed.get("issues", [])
    issues = [shorten(redact(str(item)), 700) for item in issues_raw] if isinstance(issues_raw, list) else []
    summary = shorten(redact(str(parsed.get("summary", ""))), 1400)
    if verdict not in ("PASS", "FIX_REQUIRED"):
        raise AgentError("Akzeptanzprüfung verdict muss PASS oder FIX_REQUIRED sein.")

    checks_raw = parsed.get("checks", [])
    checks: list[Any] = []
    if verdict == "PASS":
        checks, evidence_problems = self._validate_acceptance_checks(
            checks_raw,
            redact(full_patch),
        )
        if evidence_problems:
            self.logger.emit(
                "review",
                "Acceptance-PASS wegen nicht belegbarer Checks verworfen.",
                error_code="ACCEPTANCE_EVIDENCE_INVALID",
                problems=evidence_problems[:10],
            )
            return {
                "verdict": "FIX_REQUIRED",
                "summary": (
                    "Der Acceptance Reviewer meldete PASS, konnte die behaupteten Erfüllungen "
                    "aber nicht mit überprüfbaren exakten Belegen aus dem finalen Diff nachweisen."
                ),
                "issues": [
                    shorten(
                        "Acceptance-Nachweis ungültig: " + problem
                        + " Prüfe die genannte Originalanforderung am aktuellen Code und implementiere sie, falls sie fehlt.",
                        700,
                    )
                    for problem in evidence_problems[:8]
                ],
                "checks": checks,
            }
    elif isinstance(checks_raw, list):
        checks = checks_raw

    if verdict == "FIX_REQUIRED" and not issues:
        issues = [summary or "Akzeptanzprüfung fordert Korrekturen ohne Einzelpunkt."]
    return {"verdict": verdict, "summary": summary, "issues": issues, "checks": checks}
